  "Stays on this phone — kept out of Memory and never sent anywhere. Predictions are estimates, not contraception or medical advice.": "इसी फ़ोन पर रहता है — Memory से अलग और कभी कहीं नहीं भेजा जाता। अनुमान सिर्फ़ अंदाज़ा हैं, गर्भनिरोध या डॉक्टरी सलाह नहीं।",
