  "PDF ↔ Word, PowerPoint → PDF, photos → PDF, scanned paper → editable Word, Excel ↔ CSV ↔ JSON, e-books, web pages, subtitles, merge and split PDFs — on your phone. Your files are never uploaded to a converter website.": "PDF ↔ Word, PowerPoint → PDF, फ़ोटो → PDF, स्कैन किया कागज़ → एडिट होने वाला Word, Excel ↔ CSV ↔ JSON, ई-बुक, वेब पेज, सबटाइटल, PDF जोड़ना और अलग करना — आपके फ़ोन पर। आपकी फ़ाइलें कभी किसी कन्वर्टर वेबसाइट पर अपलोड नहीं होतीं।",
