  "The translation appears here": "अनुवाद यहाँ दिखेगा",
  "Every part is checked: numbers, names and codes kept exactly.": "हर हिस्सा जाँचा जाता है: नंबर, नाम और कोड बिल्कुल वैसे ही रहते हैं।",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "कोई PDF, Word फ़ाइल, किताब या वेब पेज खोलें। इसे यहीं पढ़ें और इससे चैट करें — हर जवाब बताता है कि वो किस पेज से आया। सब कुछ आपके फ़ोन पर रहता है।",
