  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "वीडियो का लिंक कॉपी करें, यहाँ पेस्ट करें, क्वालिटी चुनें — ये आपके फ़ोन के Movies फ़ोल्डर में सेव हो जाता है। सीधे वीडियो लिंक, Google Drive, Dropbox, archive.org, Wikimedia Commons और सादा वीडियो दिखाने वाले पेजों के साथ काम करता है।",
