  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "मॉडल प्रोग्राम और उसके टेस्ट लिखता है, फ़ोन उन्हें चलाता है, और कोई भी गलती सीधे मॉडल के पास ठीक करने के लिए वापस जाती है — जब तक टेस्ट पास न हो जाएँ। ऑफ़लाइन, एक बंद सैंडबॉक्स में।",
  "What should it do? e.g. “A function that splits a restaurant bill between friends, with the tip”": "इसे क्या करना है? जैसे “एक फ़ंक्शन जो रेस्टोरेंट का बिल टिप समेत दोस्तों में बाँटे”",
