  "= instant filler removal (offline).": "= तुरंत फ़ालतू शब्द हटाना (ऑफ़लाइन)।",
  "= the model rewrites it far shorter while keeping the meaning.": "= मॉडल मतलब बनाए रखते हुए इसे काफ़ी छोटा लिखता है।",
  "Result": "नतीजा",
  "Paste a wordy prompt and hit": "एक लंबा प्रॉम्प्ट पेस्ट करें और दबाएँ",
  "— it thinks about meaning, not just filler words.": "— ये सिर्फ़ फ़ालतू शब्दों पर नहीं, मतलब पर सोचता है।",
  "Text to rewrite": "दोबारा लिखने के लिए टेक्स्ट",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "AI से बना या रूखा टेक्स्ट पेस्ट करें — ये ऐसा होकर वापस आता है जैसे किसी इंसान ने लिखा हो।",
  "Your writing sample": "आपके लिखने का नमूना",
