  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "अपने लिखे कुछ पैराग्राफ़ पेस्ट करें — कोई ईमेल, मैसेज, कुछ भी आपकी अपनी आवाज़ में।",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "आपका मतलब और तथ्य बिल्कुल वैसे ही रखता है — सिर्फ़ पढ़ने का अंदाज़ बदलता है। लिखने का नमूना वैकल्पिक है लेकिन सबसे ज़्यादा फ़र्क़ इसी से पड़ता है।",
  "Rewritten": "दोबारा लिखा गया",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "रूखा या AI जैसा टेक्स्ट पेस्ट करें, अपने लिखने का नमूना जोड़ें, और ये आपकी आवाज़ में वापस आता है — वही मतलब, इंसानी लय।",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Attune के ज़रिए चैट करें — ये पूरी बातचीत पढ़ता है और हर अगला प्रॉम्प्ट और बेहतर बनाता है।",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "इस पूरी बातचीत से आप क्या चाहते हैं? (वैकल्पिक, लेकिन इससे हर प्रॉम्प्ट बेहतर होता है)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "{t} से चैट लाएँ — पूरी बातचीत या सिर्फ़ उसका आख़िरी जवाब पेस्ट करें:",
  "Paste here…": "यहाँ पेस्ट करें…",
  "Read it & suggest my reply": "पढ़कर मेरा जवाब सुझाओ",
  "What do you want to ask? Type it however you like.": "आप क्या पूछना चाहते हैं? जैसे चाहें लिखें।",
  "Optimize my prompt": "मेरा प्रॉम्प्ट बेहतर करो",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "चक्र: इरादा लिखें → बेहतर प्रॉम्प्ट पाएँ → भेजें → जवाब वापस लाएँ → हर अगला प्रॉम्प्ट और सटीक। फ़ोन ऐप में शेयर-शीट से कॉपी-पेस्ट की ज़रूरत ही नहीं रहती।",
  "Ready prompt recipes — pick one, fill the blanks, then": "तैयार प्रॉम्प्ट रेसिपी — एक चुनें, खाली जगह भरें, फिर",
