  "Core Max, Sense, Zenith, Apex and Everest run on a computer: get them in the Attune desktop app.": "Core Max, Sense, Zenith, Apex और Everest कंप्यूटर पर चलते हैं: इन्हें Attune डेस्कटॉप ऐप में पाएँ।",
  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "फ़ोन के लिए बहुत भारी — ये ऐप बंद कर सकता है। यहाँ Core या Blaze आराम से चलते हैं; ये वाला डेस्कटॉप ऐप में है।",
