  "The lock keeps others out on a shared phone. It is not encryption, and the notes still show in Mind.": "शेयर किए गए फ़ोन पर यह लॉक दूसरों को रोकता है। यह एन्क्रिप्शन नहीं है, और नोट्स Mind में फिर भी दिखते हैं।",
