  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "Pro, Attune के Google Play वर्ज़न में खरीदा जाता है — एक टैप, कार्ड से या अपने Vodafone / Orange / Etisalat बैलेंस से भुगतान, और यह अपने-आप चालू हो जाता है।",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "कभी भी Google Play → Subscriptions में जाकर रद्द करें। प्लान अपने-आप रिन्यू होता है; कुछ भेजना नहीं, किसी को मैसेज नहीं करना।",
