  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "यह लिंक नहीं है। वीडियो का लिंक कॉपी करें (यह https:// से शुरू होता है) और यहाँ पेस्ट करें।",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "{site} अपने वीडियो डाउनलोड करने नहीं देता, इसलिए Attune उन्हें सेव नहीं कर सकता (Google Play ऐसा करने वाले ऐप हटा देता है)। ये लिंक चलते हैं: सीधे वीडियो लिंक, Google Drive, Dropbox, archive.org, Wikimedia Commons, और ऐसे पेज जिनमें साधारण वीडियो फ़ाइल हो।",
  "a streaming service": "कोई स्ट्रीमिंग सेवा",
  "this site": "यह साइट",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "यह लाइव-स्ट्रीम लिंक (.m3u8) है — यह टुकड़ों में स्ट्रीम होता है और एक फ़ाइल के रूप में सेव नहीं हो सकता।",
  "Downloading works in the Android app.": "डाउनलोड Android ऐप में होता है।",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "Google Drive ने फ़ाइल नहीं दी — पक्का करें कि यह \"Anyone with the link\" के साथ शेयर है।",
  "This page plays a {site} video, which can't be downloaded.": "यह पेज {site} का वीडियो चलाता है, जो डाउनलोड नहीं हो सकता।",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "यह पेज अपना वीडियो टुकड़ों में स्ट्रीम करता है (HLS), जो एक फ़ाइल के रूप में सेव नहीं हो सकता।",
  "No downloadable video was found on that page.": "उस पेज पर डाउनलोड करने लायक कोई वीडियो नहीं मिला।",
