  "PDF · Word · PowerPoint · Excel · CSV · photos · e-books · web pages · subtitles — several photos → one PDF, several PDFs → merged": "PDF · Word · PowerPoint · Excel · CSV · फ़ोटो · ई-बुक · वेब पेज · सबटाइटल — कई फ़ोटो → एक PDF, कई PDF → एक में मिली हुई",
