  "A photo is read word for word and the text kept, so a whiteboard, a receipt or a handwritten site note becomes searchable — and anything promised on it shows up on the right.": "फ़ोटो को शब्द-दर-शब्द पढ़कर उसका टेक्स्ट रखा जाता है, ताकि व्हाइटबोर्ड, रसीद या हाथ से लिखा साइट नोट खोजा जा सके — और उसमें किया गया कोई भी वादा दाईं ओर दिखता है।",
