  "You keep using these — should it know them?": "आप ये बार-बार इस्तेमाल करते हैं — क्या इसे ये पता होने चाहिए?",
  "Tap one to fill it in. Nothing is learned until you say so.": "भरने के लिए किसी एक पर टैप करें। आपके कहे बिना कुछ नहीं सीखा जाता।",
