  "devices, is checked on the device so it activates on a plane, and sends nothing about you — only a random install id, only when you activate.": "डिवाइस पर चलती है, डिवाइस पर ही जाँची जाती है ताकि प्लेन में भी चालू हो जाए, और आपके बारे में कुछ नहीं भेजती — सिर्फ़ एक रैंडम इंस्टॉल id, वो भी सिर्फ़ चालू करते समय।",
