  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "इंस्टॉल किए गए वेट अपने-आप अपडेट नहीं होते, इसलिए जो प्रॉम्प्ट आज काम करता है वह एक साल बाद भी वैसे ही काम करेगा। फ़िंगरप्रिंट साबित करता है कि जवाब ठीक कौन-सी फ़ाइल दे रही है।",
