  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "जैसे: मैं मिस्र में एक छोटी दुकान चलाता हूँ। जब तक मैं अंग्रेज़ी में न लिखूँ, मिस्र की अरबी में जवाब दो। कीमतें EGP में बताओ।",
  "Saved when you tap outside the box. Stays on this phone.": "बॉक्स के बाहर टैप करने पर सेव हो जाता है। यह इसी फ़ोन में रहता है।",
