  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "सिर्फ़ आपका खोजा हुआ सवाल और खोले गए पेज फ़ोन से बाहर जाते हैं — आपकी बातचीत, फ़ाइलें या मेमोरी कभी नहीं।",
