  "Nothing has left the phone.": "फ़ोन से कुछ भी बाहर नहीं गया।",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \"nothing leaves this phone\".": "मॉडल खुद कभी नेटवर्क इस्तेमाल नहीं करता। लॉग में ऐप के किए या ठुकराए गए हर कनेक्शन की सिर्फ़ होस्ट और वजह दिखती है — यही \"फ़ोन से कुछ बाहर नहीं जाता\" का सबूत है।",
