  "INT4 KV cache + sliding-window eviction, so long conversations don't grow unbounded.": "INT4 KV कैश + स्लाइडिंग-विंडो हटाव, ताकि लंबी बातचीत में मेमोरी बेहिसाब न बढ़े।",
  "Storage:": "स्टोरेज:",
  "Compute": "कंप्यूट",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "प्रीफ़िल वहाँ चलता है जहाँ कंप्यूट सबसे तेज़ है, डीकोड वहाँ जहाँ बैंडविड्थ। दोनों के इस्तेमाल से काम की बैंडविड्थ ~43 से ~59 GB/s हो जाती है।",
