  "No model fits this device": "इस डिवाइस पर कोई मॉडल नहीं चलता",
  "Your real names for your real things. Every document then uses them correctly — no invented equipment names, no wrong site spellings. Stays on your devices.": "आपकी असली चीज़ों के आपके असली नाम। फिर हर दस्तावेज़ उन्हें सही इस्तेमाल करता है — न गढ़े हुए उपकरणों के नाम, न साइट की गलत स्पेलिंग। आपके डिवाइसों पर ही रहता है।",
  "Use company terminology": "कंपनी की शब्दावली इस्तेमाल करें",
