  "Everything in Attune lives only on this phone. A backup is one file, locked with your password, that you can keep anywhere.": "Attune में सब कुछ सिर्फ़ इसी फ़ोन में रहता है। बैकअप एक फ़ाइल होती है, आपके पासवर्ड से लॉक, जिसे आप कहीं भी रख सकते हैं।",
