  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "Attune के लिए नोटिफ़िकेशन बंद हैं — चालू करने के लिए टैप करें, वरना रिमाइंडर नहीं दिखेंगे।",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "रिमाइंडर 10 मिनट तक देर से आ सकते हैं। Attune के लिए “अलार्म और रिमाइंडर” की अनुमति देने को टैप करें, ताकि वे ठीक समय पर बजें।",
  "In the browser reminders are only listed — the Android app rings them.": "ब्राउज़र में रिमाइंडर सिर्फ़ सूची में दिखते हैं — Android ऐप उन्हें बजाता है।",
  "from a promise": "एक वादे से",
